# group questions, apply same case-level outcome to all reports for duplicate-question clusters when decisions agree
# Build records preserving input order.
results=[]
for r in reports:
    rid=r['reportId']; verdict,repair,edit,route,conf,evidence,reply=RULES[rid]
    results.append({'reportId':rid,'questionId':r['questionId'],'verdict':verdict,'repair':repair,'edit':edit,'route':route,'confidence':conf,'evidence':evidence,'student_reply':reply})
(ROOT/'results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\n')
# Data inventory summary
print('rules',len(RULES),'reports',len(results),'question refs matched',sum(r['questionId'] in qmap for r in reports))
